<?php
session_start();
if (empty($_SESSION['user_id'])) { header('Location: login.php'); exit; }
$role = strtolower((string)($_SESSION['user_role'] ?? 'student'));
if (!in_array($role, ['student', 'teacher', 'admin'], true)) { http_response_code(403); exit('Access denied.'); }
function ph($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
$name = (string)($_SESSION['user_name'] ?? ($role === 'student' ? 'Student' : 'Teacher'));
$error = '';
$studentStats = ['total'=>0,'submitted'=>0,'pending'=>0,'graded'=>0,'overdue'=>0,'average'=>null];
$teacherStats = ['students'=>0,'assignments'=>0,'submitted'=>0,'graded'=>0,'average'=>null];
$rows = []; $studentOptions = []; $selectedStudent = null; $selectedRows = []; $selectedStats = ['total'=>0,'submitted'=>0,'pending'=>0,'graded'=>0,'overdue'=>0,'average'=>null];
$selectedStudentId = isset($_GET['student_id']) ? (int)$_GET['student_id'] : 0;
try {
    $pdo = new PDO('mysql:host=127.0.0.1;port=3306;dbname=kanji_master;charset=utf8mb4', 'root', 'root', [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC, PDO::ATTR_EMULATE_PREPARES=>false]);
    $pdo->exec("CREATE TABLE IF NOT EXISTS teacher_kanji_assignment_students (assignment_id BIGINT UNSIGNED NOT NULL, student_id INT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', submitted_at DATETIME NULL, UNIQUE KEY uq_tkas (assignment_id,student_id), INDEX (student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $cols = $pdo->query('SHOW COLUMNS FROM teacher_kanji_assignment_students')->fetchAll(PDO::FETCH_COLUMN);
    if (!in_array('grade', $cols, true)) $pdo->exec('ALTER TABLE teacher_kanji_assignment_students ADD COLUMN grade TINYINT UNSIGNED NULL');
    if (!in_array('teacher_feedback', $cols, true)) $pdo->exec('ALTER TABLE teacher_kanji_assignment_students ADD COLUMN teacher_feedback TEXT NULL');
    if (!in_array('graded_at', $cols, true)) $pdo->exec('ALTER TABLE teacher_kanji_assignment_students ADD COLUMN graded_at DATETIME NULL');

    if ($role === 'student') {
        $q = $pdo->prepare("SELECT COUNT(*) total, SUM(CASE WHEN s.status='submitted' THEN 1 ELSE 0 END) submitted, SUM(CASE WHEN s.status IS NULL OR s.status<>'submitted' THEN 1 ELSE 0 END) pending, COUNT(s.grade) graded, AVG(s.grade) average FROM teacher_kanji_assignment_students s WHERE s.student_id=?");
        $q->execute([(int)$_SESSION['user_id']]); $stats = $q->fetch() ?: [];
        foreach (['total','submitted','pending','graded'] as $k) $studentStats[$k] = (int)($stats[$k] ?? 0);
        $studentStats['average'] = $stats['average'] !== null ? (float)$stats['average'] : null;
        $q = $pdo->prepare("SELECT a.id assignment_id,a.title,a.due_date,a.created_at,s.status,s.submitted_at,s.grade,s.teacher_feedback,s.graded_at FROM teacher_kanji_assignment_students s JOIN teacher_kanji_assignments a ON a.id=s.assignment_id WHERE s.student_id=? ORDER BY a.created_at DESC");
        $q->execute([(int)$_SESSION['user_id']]); $rows = $q->fetchAll();
        $today = date('Y-m-d');
        foreach ($rows as $r) if (($r['status'] ?? '') !== 'submitted' && !empty($r['due_date']) && substr((string)$r['due_date'], 0, 10) < $today) $studentStats['overdue']++;
    } else {
        $isAdmin = $role === 'admin';
        $ownerWhere = $isAdmin ? '' : ' WHERE a.teacher_id=?';
        $ownerParams = $isAdmin ? [] : [(int)$_SESSION['user_id']];
        $q = $pdo->prepare('SELECT COUNT(DISTINCT s.student_id) students,COUNT(DISTINCT a.id) assignments,SUM(CASE WHEN s.status="submitted" THEN 1 ELSE 0 END) submitted,COUNT(s.grade) graded,AVG(s.grade) average FROM teacher_kanji_assignments a LEFT JOIN teacher_kanji_assignment_students s ON s.assignment_id=a.id'.$ownerWhere);
        $q->execute($ownerParams); $stats = $q->fetch() ?: [];
        foreach (['students','assignments','submitted','graded'] as $k) $teacherStats[$k] = (int)($stats[$k] ?? 0);
        $teacherStats['average'] = $stats['average'] !== null ? (float)$stats['average'] : null;
        $sql = "SELECT u.id student_id,u.name,u.email,COUNT(s.assignment_id) total,SUM(CASE WHEN s.status='submitted' THEN 1 ELSE 0 END) submitted,COUNT(s.grade) graded,AVG(s.grade) average,MAX(COALESCE(s.graded_at,s.submitted_at)) last_activity FROM teacher_kanji_assignment_students s JOIN users u ON u.id=s.student_id JOIN teacher_kanji_assignments a ON a.id=s.assignment_id".$ownerWhere.' GROUP BY u.id,u.name,u.email ORDER BY u.name ASC';
        $q = $pdo->prepare($sql); $q->execute($ownerParams); $rows = $q->fetchAll();
        $studentOptions = $rows;

        if ($selectedStudentId > 0) {
            // A teacher can only open a student attached to one of their own assignments. Admins can view all.
            $studentSql = 'SELECT DISTINCT u.id student_id,u.name,u.email FROM users u JOIN teacher_kanji_assignment_students s ON s.student_id=u.id JOIN teacher_kanji_assignments a ON a.id=s.assignment_id WHERE u.id=?';
            $studentParams = [$selectedStudentId];
            if (!$isAdmin) { $studentSql .= ' AND a.teacher_id=?'; $studentParams[] = (int)$_SESSION['user_id']; }
            $studentSql .= ' LIMIT 1';
            $q = $pdo->prepare($studentSql); $q->execute($studentParams); $selectedStudent = $q->fetch() ?: null;
            if ($selectedStudent) {
                $detailSql = "SELECT a.id assignment_id,a.title,a.due_date,a.created_at,s.status,s.submitted_at,s.grade,s.teacher_feedback,s.graded_at FROM teacher_kanji_assignment_students s JOIN teacher_kanji_assignments a ON a.id=s.assignment_id WHERE s.student_id=?";
                $detailParams = [$selectedStudentId];
                if (!$isAdmin) { $detailSql .= ' AND a.teacher_id=?'; $detailParams[] = (int)$_SESSION['user_id']; }
                $detailSql .= ' ORDER BY a.created_at DESC';
                $q = $pdo->prepare($detailSql); $q->execute($detailParams); $selectedRows = $q->fetchAll();
                $selectedStats['total'] = count($selectedRows);
                foreach ($selectedRows as $r) {
                    if (($r['status'] ?? '') === 'submitted') $selectedStats['submitted']++;
                    else { $selectedStats['pending']++; if (!empty($r['due_date']) && substr((string)$r['due_date'], 0, 10) < date('Y-m-d')) $selectedStats['overdue']++; }
                    if ($r['grade'] !== null) { $selectedStats['graded']++; $selectedStats['average'] = ($selectedStats['average'] ?? 0) + (int)$r['grade']; }
                }
                if ($selectedStats['graded'] > 0) $selectedStats['average'] = $selectedStats['average'] / $selectedStats['graded'];
                else $selectedStats['average'] = null;
            } else { $error = 'That student could not be found in your assigned classes.'; }
        }
    }
} catch (Throwable $e) { error_log('Kanji Master progress: '.$e->getMessage()); $error = 'Could not load progress right now. Check that MAMP MySQL is running and the assignment tables exist.'; }
$studentGradeChart = [];
if ($role === 'student') {
    foreach (array_reverse($rows) as $r) if ($r['grade'] !== null) $studentGradeChart[] = ['label'=>(string)$r['title'],'value'=>max(0,min(100,(int)$r['grade']))];
    $studentGradeChart = array_slice($studentGradeChart, -8);
}
$detailGradeChart = [];
foreach (array_reverse($selectedRows) as $r) if ($r['grade'] !== null) $detailGradeChart[] = ['label'=>(string)$r['title'],'value'=>max(0,min(100,(int)$r['grade']))];
$detailGradeChart = array_slice($detailGradeChart, -8);
$studentOverdueRows = array_values(array_filter($rows, static fn($r) => ($r['status'] ?? '') !== 'submitted' && !empty($r['due_date']) && substr((string)$r['due_date'], 0, 10) < date('Y-m-d')));
$selectedOverdueRows = array_values(array_filter($selectedRows, static fn($r) => ($r['status'] ?? '') !== 'submitted' && !empty($r['due_date']) && substr((string)$r['due_date'], 0, 10) < date('Y-m-d')));
$studentRecentFeedback = array_values(array_filter($rows, static fn($r) => trim((string)($r['teacher_feedback'] ?? '')) !== '')); 
$studentRecentFeedback = array_slice($studentRecentFeedback, 0, 3);
$selectedRecentFeedback = array_values(array_filter($selectedRows, static fn($r) => trim((string)($r['teacher_feedback'] ?? '')) !== ''));
$selectedRecentFeedback = array_slice($selectedRecentFeedback, 0, 3);
$detailGradeDelta = count($detailGradeChart) >= 2 ? ($detailGradeChart[count($detailGradeChart)-1]['value'] - $detailGradeChart[count($detailGradeChart)-2]['value']) : null;
$studentGradeDelta = count($studentGradeChart) >= 2 ? ($studentGradeChart[count($studentGradeChart)-1]['value'] - $studentGradeChart[count($studentGradeChart)-2]['value']) : null;
function donutStyle(int $a, int $b, int $c = 0): string {
    $total = $a + $b + $c;
    if ($total <= 0) return 'background:conic-gradient(#334155 0 100%)';
    $p1 = $a / $total * 100; $p2 = ($a + $b) / $total * 100;
    return 'background:conic-gradient(#34d399 0 '.$p1.'%,#818cf8 '.$p1.'% '.$p2.'%,#fbbf24 '.$p2.'% 100%)';
}
